'use strict';
// Prepare frozen central-principal decision dates, or summarize matched 3-batch
// sensitivity. The candidate and baseline still come from native app runs.
const fs=require('node:fs'),{quant:q,boot}=require('./operating-20261110.cjs'),rd=n=>JSON.parse(fs.readFileSync('/tmp/jkq-20261111-'+n+'.json'));
const refs=['switch-real','switch-syn10','switch-syn100'].map(rd),central={};for(const j of refs)for(const[ds,caps]of Object.entries(j.sets)){central[ds]??={};for(const[cap,hs]of Object.entries(caps)){central[ds][cap]={};for(const[H,rows]of Object.entries(hs))central[ds][cap][H]=rows.filter(x=>x.inv>=.9&&x.loss<=-.3).map(x=>x.run+'|'+x.t);}}
if(process.argv[2]==='--prepare'){fs.writeFileSync('/tmp/jkq-20261111-central-d.json',JSON.stringify(central));process.exit(0);}
const out={date:'2026-11-11',note:'Fixed central D decisions; average C12/A and paired MDD differences across .99/1/1.01 before summaries',sets:{}};
for(const ds of['real','syn']){const jit=rd('switch-jit-'+ds).sets[ds];if(Object.keys(jit).length!==4)throw Error('Jitter run incomplete');out.sets[ds]={};for(const cap of[10000,100000]){const ref=refs.find(x=>x.sets[ds]?.[cap])?.sets[ds][cap][5],fixed=ref.filter(x=>x.inv>=.9&&x.loss<=-.3),map=j=>new Map(j.map(x=>[x.run+'|'+x.t,x])),maps=[map(jit[cap*.99][5]),map(ref),map(jit[cap*1.01][5])];
 const flat=rd('switch-jitter-flat-audit'),rows=fixed.map(x=>{const all=maps.map((m,i)=>{const z=m.get(x.run+'|'+x.t);if(z)return {ratio:z.C[12].v/z.A,mdd:z.C[12].mdd-z.mddA};const p=cap*[.99,1,1.01][i];if(ds!==flat.ds||p!==flat.principal||x.run!==flat.run||x.t!==flat.t||flat.shares!==0||!flat.samePolicy)throw Error('Missing non-flat fixed decision');out.flatPolicyIdentity=flat;return {ratio:1,mdd:0};});return {run:x.run,t:x.t,ratio:all.reduce((s,z)=>s+z.ratio,0)/3,mdd:all.reduce((s,z)=>s+z.mdd,0)/3};}),r=rows.map(x=>x.ratio);out.sets[ds][cap]={n:rows.length,ratio:q(r),rowBlockCI:boot(r),mdd:q(rows.map(x=>x.mdd)),front:q(rows.filter(x=>x.t<'2011').map(x=>x.ratio)),back:q(rows.filter(x=>x.t>='2011').map(x=>x.ratio)),win:r.filter(x=>x>1+1e-9).length,rows};console.log(JSON.stringify({ds,cap,...out.sets[ds][cap],rows:undefined}));}}
fs.writeFileSync('/tmp/jkq-20261111-switch-jitter-summary.json',JSON.stringify(out));
